WITH daily_loss AS ( SELECT w.w_warehouse_id AS warehouse_id, w.w_warehouse_name AS warehouse_name, cr.cr_returned_date_sk AS return_date, SUM(cr.cr_net_loss) AS daily_net_loss FROM catalog_returns cr JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk JOIN call_center cc ON cr.cr_call_center_sk = cc.cc_call_center_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY w.w_warehouse_id, w.w_warehouse_name, cr.cr_returned_date_sk ) SELECT warehouse_id, warehouse_name, return_date, daily_net_loss, LAG(daily_net_loss) OVER (PARTITION BY warehouse_id ORDER BY return_date) AS prev_daily_net_loss, daily_net_loss - LAG(daily_net_loss) OVER (PARTITION BY warehouse_id ORDER BY return_date) AS net_loss_change, CASE WHEN LAG(daily_net_loss) OVER (PARTITION BY warehouse_id ORDER BY return_date) IS NULL THEN 'N/A' WHEN (daily_net_loss - LAG(daily_net_loss) OVER (PARTITION BY warehouse_id ORDER BY return_date)) / LAG(daily_net_loss) OVER (PARTITION BY warehouse_id ORDER BY return_date) > 0.2 THEN 'Spike' ELSE 'Normal' END AS change_flag FROM daily_loss ORDER BY warehouse_id, return_date
